create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, email text, preferred_locale text not null default 'uk' check (preferred_locale in ('uk','en','it')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.locations (id uuid primary key default gen_random_uuid(), name_uk text not null, name_en text, name_it text, normalized_name text not null, ascii_name text, aliases jsonb not null default '[]'::jsonb, country_code char(2), provider_location_id text unique, latitude double precision, longitude double precision, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.routes (id uuid primary key default gen_random_uuid(), from_location_id uuid not null references public.locations(id), to_location_id uuid not null references public.locations(id), provider_route_id text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(from_location_id,to_location_id,provider_route_id), constraint routes_different_locations check (from_location_id <> to_location_id));
create table if not exists public.trips (id uuid primary key default gen_random_uuid(), route_id uuid not null references public.routes(id) on delete cascade, provider_trip_id text unique, departure_at timestamptz not null, arrival_at timestamptz, duration_minutes integer, carrier text, status text not null default 'scheduled' check (status in ('scheduled','active','cancelled','completed')), external_version text, external_updated_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.trip_stops (id uuid primary key default gen_random_uuid(), trip_id uuid not null references public.trips(id) on delete cascade, location_id uuid not null references public.locations(id), stop_order integer not null, arrival_offset interval, departure_offset interval, day_offset integer not null default 0, is_pickup boolean not null default false, is_dropoff boolean not null default false, unique(trip_id,stop_order));
create table if not exists public.trip_prices (id uuid primary key default gen_random_uuid(), trip_id uuid not null references public.trips(id) on delete cascade, currency char(3) not null default 'UAH', price numeric(12,2) not null check (price >= 0), seats_available integer not null default 0 check (seats_available >= 0), source text not null default 'provider', confirmed_at timestamptz not null default now(), expires_at timestamptz, unique(trip_id));
create table if not exists public.availability_cache (route_id uuid not null references public.routes(id) on delete cascade, travel_date date not null, trips_count integer not null default 0 check (trips_count >= 0), min_price numeric(12,2), max_price numeric(12,2), currency char(3), provider_source text, schema_version text not null default '1', confirmed_at timestamptz not null default now(), expires_at timestamptz not null, primary key(route_id,travel_date,schema_version));
create table if not exists public.provider_request_logs (id uuid primary key default gen_random_uuid(), provider text not null, operation text not null, route_key text, travel_date date, status text not null, response_code integer, cache_hit boolean not null default false, error_code text, requested_at timestamptz not null default now(), completed_at timestamptz);
create table if not exists public.popular_routes (id uuid primary key default gen_random_uuid(), route_id uuid not null references public.routes(id) on delete cascade, locale text not null check (locale in ('uk','en','it')), sort_order integer not null default 0, is_featured boolean not null default true, active boolean not null default true, unique(route_id,locale));
create table if not exists public.bookings (id uuid primary key default gen_random_uuid(), booking_number text unique not null, passenger_id uuid references auth.users(id), trip_id uuid not null references public.trips(id), status text not null default 'pending' check (status in ('pending','confirmed','cancelled','expired','refunded')), currency char(3) not null, total_amount numeric(12,2) not null check (total_amount >= 0), expires_at timestamptz, provider_booking_id text, created_at timestamptz not null default now(), confirmed_at timestamptz);
create table if not exists public.booking_passengers (id uuid primary key default gen_random_uuid(), booking_id uuid not null references public.bookings(id) on delete cascade, full_name text not null, email text, phone text, seat_number text, nationality text, document_type text, document_number text);
create table if not exists public.admin_profiles (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('super_admin','admin','content_manager','support','provider_operator')), active boolean not null default true, created_at timestamptz not null default now());